import React, { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import LoginPage from './pages/LoginPage';
import MainLayout from './components/layout/MainLayout';
import DashboardHome from './pages/DashboardHome';
import ReconciliationView from './pages/ReconciliationView';
import PartyManagement from './pages/PartyManagement';
import EmailSender from './pages/EmailSender';
import LogsReporting from './pages/LogsReporting';
import SettingsPage from './pages/SettingsPage';
import { getAuthStatus } from './services/api';

export default function App() {
  const [authenticated, setAuthenticated] = useState(false);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    getAuthStatus()
      .then(res => setAuthenticated(res.data.authenticated))
      .catch(() => setAuthenticated(false))
      .finally(() => setChecking(false));
  }, []);

  if (checking) {
    return (
      <div className="h-screen w-full flex items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-slate-200 border-t-primary-600 rounded-full animate-spin" />
          <span className="text-sm font-medium text-slate-500 animate-pulse text-center">
            Initializing Secure Session...
          </span>
        </div>
      </div>
    );
  }

  return (
    <BrowserRouter>
      <Toaster 
        position="top-right"
        toastOptions={{
          duration: 4000,
          className: 'bg-white text-slate-900 border border-slate-200 shadow-xl rounded-xl text-sm font-medium',
        }}
      />

      <Routes>
        {!authenticated ? (
          <>
            <Route path="/login" element={<LoginPage onLogin={() => setAuthenticated(true)} />} />
            <Route path="*" element={<Navigate to="/login" replace />} />
          </>
        ) : (
          <Route element={<MainLayout onLogout={() => setAuthenticated(false)} />}>
            <Route path="/dashboard" element={<DashboardHome />} />
            <Route path="/reconciliation" element={<ReconciliationView />} />
            <Route path="/parties" element={<PartyManagement />} />
            <Route path="/sender" element={<EmailSender />} />
            <Route path="/logs" element={<LogsReporting />} />
            <Route path="/settings" element={<SettingsPage />} />
            <Route path="/" element={<Navigate to="/dashboard" replace />} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </Route>
        )}
      </Routes>
    </BrowserRouter>
  );
}
